    const italic = variant == .italic or variant == .bold_italic;
    const rows = [_]struct { []const font_metrics.Glyph, bool, Table }{
        .{ font_metrics.system_ui.glyphs, false, .{ .display = .{ &display1_roman_system_ui, &display400_roman_system_ui, &display1000_roman_system_ui }, .text = .{ &text1_roman_system_ui, &text400_roman_system_ui, &text1000_roman_system_ui }, .text_weight = &weight_roman_system_ui, .tracking = &tracking_roman_system_ui } },
        .{ font_metrics.system_ui.glyphs, true, .{ .display = .{ &display1_italic_system_ui, &display400_italic_system_ui, &display1000_italic_system_ui }, .text = .{ &text1_italic_system_ui, &text400_italic_system_ui, &text1000_italic_system_ui }, .text_weight = &weight_italic_system_ui, .tracking = &tracking_italic_system_ui } },
    };
    for (rows) |row| {
        if (row[0].ptr == family.glyphs.ptr and row[1] == italic) {
            return row[2];
        }
    }
    return .{};
}
